  for (const c of CLIENTS) clients.set(c, { status: 'idle', token: 0, writing: false, revoked: 0 });

  const network: Message[] = [];
  let nextId = 1;
  const send = (from: string, to: string, action: string, data: Record<string, unknown>): void => {
    network.push({ id: `m${nextId++}`, from, to, action, data });
  };

  const onService = (m: Message): void => {
    const from = m.data.from as string;
    switch (m.action) {
      case 'Acquire':
        if (service.holder === null && service.token < MAX_GRANTS) {
          service.token += 1;
          service.holder = from;
          send(SERVICE, from, 'Granted', { token: service.token });
        } else {
          send(SERVICE, from, 'Denied', {});
        }
        return;
      case 'Release':
        if (service.holder === from && m.data.token === service.token) service.holder = null;
        return;
      case 'Write':
        if (service.holder === from && m.data.token === service.token && service.writes < MAX_WRITES) {
          service.writes += 1;
          send(SERVICE, from, 'WriteDone', {});
        } else {
          send(SERVICE, from, 'WriteRefused', {});
        }
        return;
    }
  };

  const onClient = (c: ClientState, m: Message): void => {
    switch (m.action) {
      case 'Granted': {
        if (c.status !== 'requesting') return;
        const token = m.data.token as number;
        c.token = token;
        c.status = token <= c.revoked ? 'idle' : 'holding';
        return;
      }
      case 'Denied':
        if (c.status === 'requesting') c.status = 'idle';
        return;
      case 'Revoked': {
        const token = m.data.token as number;
        if (c.status === 'holding') {
          if (token === c.token) c.status = 'idle';
        } else if (token > c.revoked) {
          c.revoked = token;
        }
        return;
      }
      case 'WriteDone':
      case 'WriteRefused':
        c.writing = false;
        return;
    }
  };

  const deliver = async (id: string): Promise<void> => {
    const i = network.findIndex((m) => m.id === id);
    if (i < 0) return;
    const [m] = network.splice(i, 1);
    if (m.to === SERVICE) onService(m);
    else {
      const c = clients.get(m.to);
      if (c) onClient(c, m);
    }
  };

  // Capture seam for verification (not part of the Host interface): the whole
  // observable state, with the network as a sorted bag of message keys.
  const snapshot = (): Record<string, unknown> => {
    const s: Record<string, unknown> = { holder: service.holder, token: service.token, writes: service.writes };
    for (const [id, c] of clients) {
      s[`${id}status`] = c.status;
      s[`${id}token`] = c.token;
      s[`${id}writing`] = c.writing;
      s[`${id}revoked`] = c.revoked;
    }
    s.net = network.map(messageKey).sort();
    return s;
  };

  const host: Host & { snapshot: typeof snapshot } = {
    snapshot,
    async inFlight() {
      return network.map((m) => ({ ...m, data: { ...m.data } }));
    },
    deliver,
    async deliverAll() {
      while (network.length > 0) await deliver(network[0].id);
    },

    async acquire(client) {
      const c = clients.get(client);
      if (!c) return refuse(`unknown client ${client}`);
      if (c.status !== 'idle') return refuse(`client ${client} is ${c.status}, not idle`);
      c.status = 'requesting';
      send(client, SERVICE, 'Acquire', { from: client });
      return ok();
    },

    async release(client) {
      const c = clients.get(client);
      if (!c) return refuse(`unknown client ${client}`);
      if (c.status !== 'holding') return refuse(`client ${client} does not hold the lease`);
      c.status = 'idle';
      send(client, SERVICE, 'Release', { from: client, token: c.token });
      return ok();
    },

    async write(client) {
      const c = clients.get(client);
      if (!c) return refuse(`unknown client ${client}`);
      if (c.status !== 'holding') return refuse(`client ${client} does not hold the lease`);
      if (c.writing) return refuse(`client ${client} already has a write waiting for an answer`);
      c.writing = true;
      send(client, SERVICE, 'Write', { from: client, token: c.token });
      return ok();
    },

    async expire() {
      if (service.holder === null) return refuse('no client holds the lease');
      const former = service.holder;
      service.holder = null;
      send(SERVICE, former, 'Revoked', { token: service.token });
      return ok();
    },

    async lease() {
      return { holder: service.holder, token: service.token, writes: service.writes };
    },

    async client(client): Promise<ClientView | null> {
      const c = clients.get(client);
      if (!c) return null;
      return { status: c.status, token: c.token, writing: c.writing };
    },
  };
