'use strict';
// SAM v2 strict spec of the lease with fencing tokens: the service, two
// clients, and the network as a sorted bag of message keys
// `Action|from|to|token` (token empty when the message carries none).

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const CLIENTS = ['c0', 'c1'];
const MAX_GRANTS = 2;
const MAX_WRITES = 2;

const INITIAL_STATE = {
  holder: null, token: 0, writes: 0,
  c0status: 'idle', c0token: 0, c0writing: false, c0revoked: 0,
  c1status: 'idle', c1token: 0, c1writing: false, c1revoked: 0,
  net: [],
};

const key = (action, from, to, token) => `${action}|${from}|${to}|${token === undefined ? '' : token}`;
const add = (net, ...msgs) => [...net, ...msgs].sort();
const remove = (net, msg) => { const i = net.indexOf(msg); return [...net.slice(0, i), ...net.slice(i + 1)]; };

const MESSAGES = [];
for (const c of CLIENTS) {
  MESSAGES.push(key('Acquire', c, 'lease'));
  for (const t of [1, 2]) MESSAGES.push(key('Release', c, 'lease', t), key('Write', c, 'lease', t));
  MESSAGES.push(key('Denied', 'lease', c), key('WriteDone', 'lease', c), key('WriteRefused', 'lease', c));
  for (const t of [1, 2]) MESSAGES.push(key('Granted', 'lease', c, t), key('Revoked', 'lease', c, t));
}

const clientDomain = [{ client: 'c0' }, { client: 'c1' }, { client: 'c2' }];
const clientSchema = { client: { type: 'string' } };
const ALL = Object.keys(INITIAL_STATE);
const clientKeys = (c) => [`${c}status`, `${c}token`, `${c}writing`, `${c}revoked`];
const others = (...written) => ALL.filter((k) => !written.includes(k));

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      holder: { type: ['string', 'null'] },
      token: { type: 'number' },
      writes: { type: 'number' },
      c0status: { type: 'string' }, c0token: { type: 'number' }, c0writing: { type: 'boolean' }, c0revoked: { type: 'number' },
      c1status: { type: 'string' }, c1token: { type: 'number' }, c1writing: { type: 'boolean' }, c1revoked: { type: 'number' },
      net: { type: 'array' },
    },
    actions: {
      ACQUIRE: { action: (data = {}) => ({ ...data }), schema: clientSchema, domain: clientDomain },
      RELEASE: { action: (data = {}) => ({ ...data }), schema: clientSchema, domain: clientDomain },
      WRITE: { action: (data = {}) => ({ ...data }), schema: clientSchema, domain: clientDomain },
      EXPIRE: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      DELIVER: {
        action: (data = {}) => ({ ...data }),
        schema: { msg: { type: 'string' } },
        domain: MESSAGES.map((msg) => ({ msg })),
      },
    },
    acceptors: {
      ACQUIRE: (model) => (p, { reject, next, unchanged }) => {
        const c = p.client;
        if (!CLIENTS.includes(c)) return reject('unknown-client');
        if (model[`${c}status`] !== 'idle') return reject('not-idle');
        next[`${c}status`] = 'requesting';
        next.net = add(model.net, key('Acquire', c, 'lease'));
        unchanged(...others(`${c}status`, 'net'));
      },
      RELEASE: (model) => (p, { reject, next, unchanged }) => {
        const c = p.client;
        if (!CLIENTS.includes(c)) return reject('unknown-client');
        if (model[`${c}status`] !== 'holding') return reject('not-holding');
        next[`${c}status`] = 'idle';
        next.net = add(model.net, key('Release', c, 'lease', model[`${c}token`]));
        unchanged(...others(`${c}status`, 'net'));
      },
      WRITE: (model) => (p, { reject, next, unchanged }) => {
        const c = p.client;
        if (!CLIENTS.includes(c)) return reject('unknown-client');
        if (model[`${c}status`] !== 'holding') return reject('not-holding');
        if (model[`${c}writing`]) return reject('write-pending');
        next[`${c}writing`] = true;
        next.net = add(model.net, key('Write', c, 'lease', model[`${c}token`]));
        unchanged(...others(`${c}writing`, 'net'));
      },
      EXPIRE: (model) => (p, { reject, next, unchanged }) => {
        if (model.holder === null) return reject('no-holder');
        next.holder = null;
        next.net = add(model.net, key('Revoked', 'lease', model.holder, model.token));
        unchanged(...others('holder', 'net'));
      },
      DELIVER: (model) => (p, { reject, next, unchanged }) => {
        if (!model.net.includes(p.msg)) return reject('not-in-flight');
        const [action, from, to, tok] = p.msg.split('|');
        const token = tok === '' ? undefined : Number(tok);
        const net = remove(model.net, p.msg);
        if (to === 'lease') {
          if (action === 'Acquire') {
            if (model.holder === null && model.token < MAX_GRANTS) {
              next.token = model.token + 1;
              next.holder = from;
              next.net = add(net, key('Granted', 'lease', from, model.token + 1));
              unchanged(...others('token', 'holder', 'net'));
            } else {
              next.net = add(net, key('Denied', 'lease', from));
              unchanged(...others('net'));
            }
            return;
          }
          if (action === 'Release') {
            if (model.holder === from && token === model.token) next.holder = null;
            else unchanged('holder');
            next.net = net;
            unchanged(...others('holder', 'net'));
            return;
          }
          // Write
          if (model.holder === from && token === model.token && model.writes < MAX_WRITES) {
            next.writes = model.writes + 1;
            next.net = add(net, key('WriteDone', 'lease', from));
            unchanged(...others('writes', 'net'));
          } else {
            next.net = add(net, key('WriteRefused', 'lease', from));
            unchanged(...others('net'));
          }
          return;
        }
        const c = to;
        const [S, T, W, R] = clientKeys(c);
        next.net = net;
        if (action === 'Granted') {
          if (model[S] === 'requesting') {
            next[T] = token;
            next[S] = token <= model[R] ? 'idle' : 'holding';
            unchanged(...others('net', S, T));
          } else unchanged(...others('net'));
        } else if (action === 'Denied') {
          if (model[S] === 'requesting') {
            next[S] = 'idle';
            unchanged(...others('net', S));
          } else unchanged(...others('net'));
        } else if (action === 'Revoked') {
          if (model[S] === 'holding') {
            if (token === model[T]) { next[S] = 'idle'; unchanged(...others('net', S)); }
            else unchanged(...others('net'));
          } else if (token > model[R]) {
            next[R] = token;
            unchanged(...others('net', R));
          } else unchanged(...others('net'));
        } else {
          // WriteDone / WriteRefused
          next[W] = false;
          unchanged(...others('net', W));
        }
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  ACQUIRE: (data = {}) => intents.ACQUIRE(data),
  RELEASE: (data = {}) => intents.RELEASE(data),
  WRITE: (data = {}) => intents.WRITE(data),
  EXPIRE: (data = {}) => intents.EXPIRE(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

