test('at most 2 writes', async () => {
  const h = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  for (let i = 0; i < 3; i++) { await h.write('c0'); await h.deliverAll(); }
  assert.equal((await h.lease()).writes, 2);
});

// Random schedules: check the brief's conclusion on the real implementation.
test('random schedules keep the invariants', async () => {
  let seed = 12345;
  const rnd = (n) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
  for (let run = 0; run < 3000; run++) {
    const h = await createHost();
    for (let step = 0; step < 30; step++) {
      const fl = await h.inFlight();
      const k = rnd(fl.length > 0 ? 6 : 4);
      const c = ['c0', 'c1'][rnd(2)];
      const pre = await h.lease();
      let delivered = null;
      if (k === 0) await h.acquire(c);
      else if (k === 1) await h.release(c);
      else if (k === 2) await h.write(c);
      else if (k === 3) await h.expire();
      else { delivered = fl[rnd(fl.length)]; await h.deliver(delivered.id); }
      const post = await h.lease();
      if (post.writes !== pre.writes) {
        assert.equal(delivered.action, 'Write');
        assert.equal(delivered.from, pre.holder);
        assert.equal(delivered.data.token, pre.token);
      }
      const views = { c0: await h.client('c0'), c1: await h.client('c1') };
      const current = Object.values(views).filter((v) => v.status === 'holding' && v.token === post.token);
      assert.ok(current.length <= 1);
      if ((await h.inFlight()).length === 0) {
        for (const id of ['c0', 'c1']) assert.equal(views[id].status === 'holding', post.holder === id);
      }
    }
  }
});

