import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const only = async (h, action, to) => {
  const ms = (await h.inFlight()).filter((m) => m.action === action && (!to || m.to === to));
  assert.equal(ms.length, 1, `one ${action} in flight`);
  return ms[0];
};

test('fresh system', async () => {
  const h = await createHost();
  assert.deepEqual(await h.lease(), { holder: null, token: 0, writes: 0 });
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 0, writing: false });
  assert.equal(await h.client('c2'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('unknown client and wrong states are refused', async () => {
  const h = await createHost();
  for (const cmd of ['acquire', 'release', 'write']) assert.equal((await h[cmd]('c9')).ok, false);
  assert.equal((await h.release('c0')).ok, false);
  assert.equal((await h.write('c0')).ok, false);
  assert.equal((await h.expire()).ok, false);
  assert.ok((await h.acquire('c0')).ok);
  assert.equal((await h.acquire('c0')).ok, false);
  assert.equal((await h.inFlight()).length, 1);
});

test('acquire, write, release', async () => {
  const h = await createHost();
  await h.acquire('c0');
  const m = await only(h, 'Acquire');
  assert.deepEqual({ from: m.from, to: m.to, data: m.data }, { from: 'c0', to: 'lease', data: { from: 'c0' } });
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'holding', token: 1, writing: false });
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 0 });
  assert.ok((await h.write('c0')).ok);
  assert.equal((await h.write('c0')).ok, false);
  assert.deepEqual((await only(h, 'Write')).data, { from: 'c0', token: 1 });
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 1 });
  assert.equal((await h.client('c0')).writing, false);
  assert.ok((await h.release('c0')).ok);
  assert.deepEqual((await only(h, 'Release')).data, { from: 'c0', token: 1 });
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: null, token: 1, writes: 1 });
  assert.equal((await h.client('c0')).status, 'idle');
});

test('second requester denied while held; at most 2 grants', async () => {
  const h = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  await h.acquire('c1'); await h.deliverAll();
  assert.equal((await h.client('c1')).status, 'idle');
  await h.release('c0'); await h.deliverAll();
  await h.acquire('c1'); await h.deliverAll();
  assert.deepEqual(await h.client('c1'), { status: 'holding', token: 2, writing: false });
  await h.release('c1'); await h.deliverAll();
  await h.acquire('c0'); await h.deliverAll();
  assert.equal((await h.client('c0')).status, 'idle');
  assert.deepEqual(await h.lease(), { holder: null, token: 2, writes: 0 });
});

test('stale holder write is refused after expire', async () => {
  const h = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  assert.ok((await h.expire()).ok);
  assert.deepEqual((await only(h, 'Revoked')).data, { token: 1 });
  await h.write('c0');
  await h.deliver((await only(h, 'Write')).id);
  await only(h, 'WriteRefused');
  assert.equal((await h.lease()).writes, 0);
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 1, writing: false });
});

test('Revoked before Granted leaves the client idle', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await h.deliver((await only(h, 'Acquire')).id);
  await h.expire();
  await h.deliver((await only(h, 'Revoked')).id);
  assert.equal((await h.client('c0')).status, 'requesting');
  await h.deliver((await only(h, 'Granted')).id);
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 1, writing: false });
  assert.deepEqual(await h.lease(), { holder: null, token: 1, writes: 0 });
});

test('one write per grant, at most 2 writes', async () => {
  const h = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  await h.write('c0'); await h.deliverAll();
  assert.equal((await h.lease()).writes, 1);
  await h.write('c0');
  await h.deliver((await only(h, 'Write')).id);
  await only(h, 'WriteRefused');
  await h.deliverAll();
  assert.equal((await h.lease()).writes, 1);
  assert.equal((await h.client('c0')).writing, false);
  await h.release('c0'); await h.deliverAll();
  await h.acquire('c1'); await h.deliverAll();
  await h.write('c1'); await h.deliverAll();
  await h.write('c1'); await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c1', token: 2, writes: 2 });
});

// Random schedules: check the brief's conclusion on the real implementation.
test('random schedules keep the invariants', async () => {
  let seed = 12345;
  const rnd = (n) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
  for (let run = 0; run < 3000; run++) {
    const h = await createHost();
    for (let step = 0; step < 30; step++) {
      const fl = await h.inFlight();
      const k = rnd(fl.length > 0 ? 6 : 4);
      const c = ['c0', 'c1'][rnd(2)];
      const pre = await h.lease();
      let delivered = null;
      if (k === 0) await h.acquire(c);
      else if (k === 1) await h.release(c);
      else if (k === 2) await h.write(c);
      else if (k === 3) await h.expire();
      else { delivered = fl[rnd(fl.length)]; await h.deliver(delivered.id); }
      const post = await h.lease();
      if (post.writes !== pre.writes) {
        assert.equal(delivered.action, 'Write');
        assert.equal(delivered.from, pre.holder);
        assert.equal(delivered.data.token, pre.token);
      }
      const views = { c0: await h.client('c0'), c1: await h.client('c1') };
      const current = Object.values(views).filter((v) => v.status === 'holding' && v.token === post.token);
      assert.ok(current.length <= 1);
      if ((await h.inFlight()).length === 0) {
        for (const id of ['c0', 'c1']) assert.equal(views[id].status === 'holding', post.holder === id);
      }
    }
  }
});

prompt:
The brief has changed. Here is the change, in addition to everything the brief said before:

# Change 3: stop waiting for a grant

A client can now stop wanting the lease while its request is on its way. The service still answers, and if the answer is a grant, the client gives the lease straight back.

- `cancelAcquire(client)`: a requesting client becomes **abandoning**. Refused otherwise.
- On `Granted`, an abandoning client records the token and gives the lease back at once: it becomes **releasing** and sends `Release` with that token, as `release` does. On `Denied`, it becomes **idle**.
- `acquire` is refused while the client is abandoning.

`status` in the client view can now also be `"abandoning"`. Everything else is as before.

The host interface is now as follows, and `host.ts` has been updated to match.

```ts
// T10 after change 3, a lease with fencing tokens, acknowledged releases and cancelled requests: the host interface every arm implements (PT13, S91).

/** A message sent by one part of the system to another, not yet delivered. */
export interface Message {
  id: string;
  from: string;
  to: string;
  action: string;
  data: Record<string, unknown>;
}

/** The network: nothing is delivered until deliver or deliverAll is called. */
export interface Network {
  /** Every message in transit, in no promised order. */
  inFlight(): Promise<Message[]>;
  /** Deliver one message in transit, by its id. */
  deliver(id: string): Promise<void>;
  /** Deliver every message in transit, and every message those deliveries send, until none is left. */
  deliverAll(): Promise<void>;
