const onClient = (c: ClientState, m: Message): void => {
  switch (m.action) {
    case 'Granted': {
      if (c.status !== 'requesting') return;
      const token = m.data.token as number;
      c.token = token;
      c.status = token <= c.revoked ? 'idle' : 'holding';
      return;
    }
    case 'Denied':
      if (c.status === 'requesting') c.status = 'idle';
      return;
    case 'Revoked': {
      const token = m.data.token as number;
      if (c.status === 'releasing') return;
      if (c.status === 'holding') {
        if (token === c.token) c.status = 'idle';
      } else if (token > c.revoked) {
        c.revoked = token;
      }
      return;
    }
    case 'Released':
      if (c.status === 'releasing') c.status = 'idle';
      return;
    case 'WriteDone':
    case 'WriteRefused':
      c.writing = false;
      return;
  }
};

const deliver = async (id: string): Promise<void> => {
  const i = network.findIndex((m) => m.id === id);
  if (i < 0) return;
  const [m] = network.splice(i, 1);
  if (m.to === SERVICE) onService(m);
  else {
    const c = clients.get(m.to);
    if (c) onClient(c, m);
  }
};

