// Rules the brief requires of the lease with fencing tokens.
const CLIENTS = ['c0', 'c1'];

const holdsCurrent = (s, c) => s[`${c}status`] === 'holding' && s[`${c}token`] === s.token;

export const stateInvariants = [
  {
    name: 'at-most-one-client-holds-current-token',
    pred: (s) => CLIENTS.filter((c) => holdsCurrent(s, c)).length <= 1,
  },
  {
    name: 'quiescent-client-and-service-agree',
    // once no message is in transit, a client holds the lease exactly when the service says so
    pred: (s) => s.net.length > 0 || CLIENTS.every((c) => (s[`${c}status`] === 'holding') === (s.holder === c)),
  },
  {
    name: 'quiescent-no-client-waits',
    // with nothing in transit, no client is still requesting or releasing
    pred: (s) => s.net.length > 0 || CLIENTS.every((c) => ['idle', 'holding'].includes(s[`${c}status`])),
  },
  {
    name: 'releasing-client-awaits-its-ack',
    pred: (s) => CLIENTS.every((c) => s[`${c}status`] !== 'releasing' ||
      s.net.some((m) => m.startsWith(`Release|${c}|`) || m.startsWith(`Released|lease|${c}|`))),
  },
  {
    name: 'abandoning-client-awaits-an-answer',
    pred: (s) => CLIENTS.every((c) => s[`${c}status`] !== 'abandoning' ||
      s.net.some((m) => m === `Acquire|${c}|lease|` || /^(Granted|Denied)\|lease\|/.test(m) && m.split('|')[2] === c)),
  },
  {
    name: 'quiescent-holder-has-current-token',
    pred: (s) => s.net.length > 0 || s.holder === null || s[`${s.holder}token`] === s.token,
  },
  {
    name: 'service-holder-was-granted-current-token',
    pred: (s) => s.holder === null || s.token > 0,
  },
  { name: 'at-most-two-grants', pred: (s) => s.token >= 0 && s.token <= 2 },
  { name: 'at-most-two-writes', pred: (s) => s.writes >= 0 && s.writes <= 2 },
  // one write per grant: never more writes taken than leases granted
  { name: 'writes-never-exceed-grants', pred: (s) => s.writes <= s.token },
  {
    name: 'client-token-never-ahead-of-service',
    pred: (s) => CLIENTS.every((c) => s[`${c}token`] <= s.token && s[`${c}revoked`] <= s.token),
  },
];

export const transitionInvariants = [
  {
    name: 'writes-only-from-holder-with-current-token',
    pred: (pre, action, data, post) => {
      if (post.writes === pre.writes) return true;
      if (action !== 'DELIVER' || post.writes !== pre.writes + 1) return false;
      const [act, from, , tok] = data.msg.split('|');
      return act === 'Write' && pre.holder === from && Number(tok) === pre.token;
