import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const only = async (h, action, to) => {
  const ms = (await h.inFlight()).filter((m) => m.action === action && (!to || m.to === to));
  assert.equal(ms.length, 1, `one ${action} in flight`);
  return ms[0];
};

test('fresh system', async () => {
  const h = await createHost();
  assert.deepEqual(await h.lease(), { holder: null, token: 0, writes: 0 });
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 0, writing: false });
  assert.equal(await h.client('c2'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('unknown client and wrong states are refused', async () => {
  const h = await createHost();
  for (const cmd of ['acquire', 'release', 'write']) assert.equal((await h[cmd]('c9')).ok, false);
  assert.equal((await h.release('c0')).ok, false);
  assert.equal((await h.write('c0')).ok, false);
  assert.equal((await h.expire()).ok, false);
  assert.ok((await h.acquire('c0')).ok);
  assert.equal((await h.acquire('c0')).ok, false);
  assert.equal((await h.inFlight()).length, 1);
});

test('acquire, write, release', async () => {
  const h = await createHost();
  await h.acquire('c0');
  const m = await only(h, 'Acquire');
  assert.deepEqual({ from: m.from, to: m.to, data: m.data }, { from: 'c0', to: 'lease', data: { from: 'c0' } });
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'holding', token: 1, writing: false });
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 0 });
  assert.ok((await h.write('c0')).ok);
  assert.equal((await h.write('c0')).ok, false);
  assert.deepEqual((await only(h, 'Write')).data, { from: 'c0', token: 1 });
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 1 });
  assert.equal((await h.client('c0')).writing, false);
  assert.ok((await h.release('c0')).ok);
  assert.deepEqual((await only(h, 'Release')).data, { from: 'c0', token: 1 });
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: null, token: 1, writes: 1 });
  assert.equal((await h.client('c0')).status, 'idle');
});

